FILE: app/src/orbit-camera.ts
```ts
import { attachControl, createArcRotateCamera } from "@babylonjs/lite";
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";

export function createOrbitCamera(canvas: HTMLCanvasElement, scene: SceneContext): ArcRotateCamera {
  const camera = createArcRotateCamera(0, Math.PI / 2, 10, [0, 0, 0]);
  attachControl(camera, canvas, scene, { keyboard: true });
  return camera;
}
```

I added `src/orbit-camera.ts`, creating a radius-10 `ArcRotateCamera` aimed at the origin and attaching the canvas controls with keyboard enabled. I assumed `Vec3` is a `[x, y, z]` tuple and used `attachControl`'s `keyboard` option rather than the standalone `enableArcRotateKeyboardControls`, which is the main thing I wasn't sure of.
